//! Dispatch for `Expression::ExtraBuiltinFunctionCall` — layout helper
//! functions generated by the LLR's layout lowering pass.

use crate::Value;
use crate::eval::{EvalContext, eval_expression};
use i_slint_compiler::llr::{Expression, FlexboxMeasureCell, FlexboxMeasureCellKind};
use i_slint_core::SharedVector;
use i_slint_core::layout::{
    BoxLayoutData, FlexboxLayoutData, FlexboxLayoutItemInfo, GridLayoutData, GridLayoutInputData,
    LayoutInfo, LayoutItemInfo, Padding,
};
use i_slint_core::model::Model;
use i_slint_core::slice::Slice;

// ── Value → layout-type converters ──────────────────────────────────────────

fn to_f32(v: &Value) -> f32 {
    match v {
        Value::Number(n) => *n as f32,
        _ => 0.,
    }
}

fn to_padding(v: &Value) -> Padding {
    let Value::Struct(s) = v else { return Padding::default() };
    let f = |k| match s.get_field(k) {
        Some(Value::Number(n)) => *n as f32,
        _ => 0.,
    };
    Padding { begin: f("begin"), end: f("end") }
}

fn to_enum<T: std::str::FromStr + Default>(v: &Value) -> T {
    match v {
        Value::EnumerationValue(_, n) => n.parse().unwrap_or_default(),
        _ => T::default(),
    }
}

fn to_cells(v: &Value) -> Vec<LayoutItemInfo> {
    let Value::Model(m) = v else { return Vec::new() };
    (0..m.row_count())
        .filter_map(|i| {
            let Value::Struct(s) = m.row_data(i)? else { return None };
            let c = s.get_field("constraint")?;
            Some(LayoutItemInfo {
                constraint: c.clone().try_into().unwrap_or_default(),
                // Only set for a box layout's cross-axis cells; absent means `auto`.
                cross_axis_self_alignment: s
                    .get_field("cross-axis-self-alignment")
                    .map(to_enum)
                    .unwrap_or_default(),
            })
        })
        .collect()
}

/// Convert one `Value::Struct` produced by the LLR's flexbox lowering:
/// a `FlexboxLayoutItemInfo` with a `constraint` and a nested `props` field.
/// `Struct::get_field` normalizes identifiers, so the kebab-case keys the
/// lowering emits match regardless of spelling.
pub(crate) fn flexbox_item_info_from_struct(s: &crate::api::Struct) -> FlexboxLayoutItemInfo {
    let constraint: LayoutInfo =
        s.get_field("constraint").cloned().and_then(|v| v.try_into().ok()).unwrap_or_default();
    let props = match s.get_field("props") {
        Some(Value::Struct(p)) => flex_props_from_struct(p),
        _ => Default::default(),
    };
    FlexboxLayoutItemInfo { constraint, props }
}

/// Convert one `Value::Struct` produced by the LLR's flexbox lowering for a
/// `FlexItemProps`.
pub(crate) fn flex_props_from_struct(
    s: &crate::api::Struct,
) -> i_slint_core::layout::FlexItemProps {
    i_slint_core::layout::FlexItemProps {
        cross_axis_self_alignment: s
            .get_field("cross-axis-self-alignment")
            .map(to_enum)
            .unwrap_or_default(),
        layout_order: match s.get_field("layout-order") {
            Some(Value::Number(n)) => *n as i32,
            _ => 0,
        },
    }
}

fn to_flex_props(v: &Value) -> Vec<i_slint_core::layout::FlexItemProps> {
    let Value::Model(m) = v else { return Vec::new() };
    (0..m.row_count())
        .filter_map(|i| {
            let Value::Struct(s) = m.row_data(i)? else { return None };
            Some(flex_props_from_struct(&s))
        })
        .collect()
}

fn to_u32_vec(v: &Value) -> Vec<u32> {
    let Value::Model(m) = v else { return Vec::new() };
    (0..m.row_count())
        .filter_map(|i| match m.row_data(i)? {
            Value::Number(n) => Some(n as u32),
            _ => None,
        })
        .collect()
}

fn to_grid_input_data(v: &Value) -> Vec<GridLayoutInputData> {
    let Value::Model(m) = v else { return Vec::new() };
    (0..m.row_count())
        .filter_map(|i| {
            let Value::Struct(s) = m.row_data(i)? else { return None };
            let f = |k: &str| match s.get_field(k) {
                Some(Value::Number(n)) => *n as f32,
                _ => 0.,
            };
            Some(GridLayoutInputData {
                new_row: matches!(s.get_field("new_row"), Some(Value::Bool(true))),
                col: f("col"),
                row: f("row"),
                colspan: f("colspan"),
                rowspan: f("rowspan"),
            })
        })
        .collect()
}

fn to_array_of_u16(v: &Value) -> SharedVector<u16> {
    match v {
        Value::ArrayOfU16(v) => v.clone(),
        _ => Default::default(),
    }
}

fn to_dialog_roles(v: &Value) -> Vec<i_slint_core::items::DialogButtonRole> {
    let Value::Model(m) = v else { return Vec::new() };
    (0..m.row_count())
        .filter_map(|i| match m.row_data(i)? {
            Value::EnumerationValue(_, n) => n.parse().ok(),
            _ => None,
        })
        .collect()
}

fn sf32(s: &crate::api::Struct, k: &str) -> f32 {
    match s.get_field(k) {
        Some(Value::Number(n)) => *n as f32,
        _ => 0.,
    }
}

// ── Dispatch ────────────────────────────────────────────────────────────────

pub(crate) fn call_extra_builtin(
    ctx: &mut EvalContext,
    name: &str,
    arguments: &[Expression],
) -> Value {
    let a: Vec<Value> = arguments.iter().map(|e| eval_expression(ctx, e)).collect();

    match name {
        "box_layout_info" => {
            let c = to_cells(&a[0]);
            i_slint_core::layout::box_layout_info(
                Slice::from_slice(&c),
                to_f32(&a[1]),
                &to_padding(&a[2]),
                to_enum(&a[3]),
            )
            .into()
        }
        "box_layout_info_ortho" => {
            let c = to_cells(&a[0]);
            i_slint_core::layout::box_layout_info_ortho(Slice::from_slice(&c), &to_padding(&a[1]))
                .into()
        }
        "organize_dialog_button_layout" => {
            let input = to_grid_input_data(&a[0]);
            let roles = to_dialog_roles(&a[1]);
            Value::ArrayOfU16(i_slint_core::layout::organize_dialog_button_layout(
                Slice::from_slice(&input),
                Slice::from_slice(&roles),
            ))
        }
        "organize_grid_layout" => {
            let (input, ri, rs) = (to_grid_input_data(&a[0]), to_u32_vec(&a[1]), to_u32_vec(&a[2]));
            Value::ArrayOfU16(i_slint_core::layout::organize_grid_layout(
                Slice::from_slice(&input),
                Slice::from_slice(&ri),
                Slice::from_slice(&rs),
            ))
        }
        "grid_layout_info" => {
            let (c, ri, rs) = (to_cells(&a[1]), to_u32_vec(&a[2]), to_u32_vec(&a[3]));
            i_slint_core::layout::grid_layout_info(
                to_array_of_u16(&a[0]),
                Slice::from_slice(&c),
                Slice::from_slice(&ri),
                Slice::from_slice(&rs),
                to_f32(&a[4]),
                &to_padding(&a[5]),
                to_enum(&a[6]),
            )
            .into()
        }
        "solve_grid_layout" => {
            let (c, ri, rs) = (to_cells(&a[1]), to_u32_vec(&a[3]), to_u32_vec(&a[4]));
            let Value::Struct(s) = &a[0] else { return Value::LayoutCache(Default::default()) };
            Value::LayoutCache(i_slint_core::layout::solve_grid_layout(
                &GridLayoutData {
                    size: sf32(s, "size"),
                    spacing: sf32(s, "spacing"),
                    padding: s.get_field("padding").map(to_padding).unwrap_or_default(),
                    organized_data: s
                        .get_field("organized_data")
                        .map(to_array_of_u16)
                        .unwrap_or_default(),
                },
                Slice::from_slice(&c),
                to_enum(&a[2]),
                Slice::from_slice(&ri),
                Slice::from_slice(&rs),
            ))
        }
        "solve_box_layout" => {
            let ri = to_u32_vec(&a[1]);
            let Value::Struct(s) = &a[0] else { return Value::LayoutCache(Default::default()) };
            let cells = s.get_field("cells").map(to_cells).unwrap_or_default();
            Value::LayoutCache(i_slint_core::layout::solve_box_layout(
                &BoxLayoutData {
                    size: sf32(s, "size"),
                    spacing: sf32(s, "spacing"),
                    padding: s.get_field("padding").map(to_padding).unwrap_or_default(),
                    alignment: s.get_field("alignment").map(to_enum).unwrap_or_default(),
                    cells: Slice::from_slice(&cells),
                },
                Slice::from_slice(&ri),
            ))
        }
        "solve_box_layout_ortho" => {
            let ri = to_u32_vec(&a[1]);
            let Value::Struct(s) = &a[0] else { return Value::LayoutCache(Default::default()) };
            let cells = s.get_field("cells").map(to_cells).unwrap_or_default();
            Value::LayoutCache(i_slint_core::layout::solve_box_layout_ortho(
                &i_slint_core::layout::BoxLayoutOrthoData {
                    size: sf32(s, "size"),
                    padding: s.get_field("padding").map(to_padding).unwrap_or_default(),
                    cross_axis_alignment: s
                        .get_field("cross_axis_alignment")
                        .map(to_enum)
                        .unwrap_or_default(),
                    cells: Slice::from_slice(&cells),
                },
                Slice::from_slice(&ri),
            ))
        }
        "solve_flexbox_layout" => {
            let ri = to_u32_vec(&a[1]);
            let Value::Struct(s) = &a[0] else { return Value::LayoutCache(Default::default()) };
            let (ch, cv) = (
                s.get_field("cells_h").map(to_cells).unwrap_or_default(),
                s.get_field("cells_v").map(to_cells).unwrap_or_default(),
            );
            let fp = s.get_field("flex_props").map(to_flex_props).unwrap_or_default();
            Value::LayoutCache(i_slint_core::layout::solve_flexbox_layout(
                &FlexboxLayoutData {
                    width: sf32(s, "width"),
                    height: sf32(s, "height"),
                    spacing_h: sf32(s, "spacing_h"),
                    spacing_v: sf32(s, "spacing_v"),
                    padding_h: s.get_field("padding_h").map(to_padding).unwrap_or_default(),
                    padding_v: s.get_field("padding_v").map(to_padding).unwrap_or_default(),
                    alignment: s.get_field("alignment").map(to_enum).unwrap_or_default(),
                    direction: s.get_field("direction").map(to_enum).unwrap_or_default(),
                    cross_axis_line_alignment: s
                        .get_field("cross_axis_line_alignment")
                        .map(to_enum)
                        .unwrap_or_default(),
                    cross_axis_alignment: s
                        .get_field("cross_axis_alignment")
                        .map(to_enum)
                        .unwrap_or_default(),
                    flex_wrap: s.get_field("flex_wrap").map(to_enum).unwrap_or_default(),
                    cells_h: Slice::from_slice(&ch),
                    cells_v: Slice::from_slice(&cv),
                    flex_props: Slice::from_slice(&fp),
                },
                Slice::from_slice(&ri),
            ))
        }
        "flexbox_layout_info_main_axis" => {
            let cells = to_cells(&a[0]);
            i_slint_core::layout::flexbox_layout_info_main_axis(
                Slice::from_slice(&cells),
                to_f32(&a[1]),
                &to_padding(&a[2]),
                to_enum(&a[3]),
            )
            .into()
        }
        "flexbox_layout_unwrapped_main" => {
            let cells = to_cells(&a[0]);
            Value::Number(i_slint_core::layout::flexbox_layout_unwrapped_main(
                Slice::from_slice(&cells),
                to_f32(&a[1]),
                &to_padding(&a[2]),
            ) as f64)
        }
        "flexbox_layout_info_cross_axis" => {
            let (ch, cv) = (to_cells(&a[0]), to_cells(&a[1]));
            let fp = to_flex_props(&a[2]);
            i_slint_core::layout::flexbox_layout_info_cross_axis(
                Slice::from_slice(&ch),
                Slice::from_slice(&cv),
                Slice::from_slice(&fp),
                to_f32(&a[3]),
                to_f32(&a[4]),
                &to_padding(&a[5]),
                &to_padding(&a[6]),
                to_enum(&a[7]),
                to_enum(&a[8]),
                to_enum(&a[9]),
                to_f32(&a[10]),
            )
            .into()
        }
        other => unimplemented!("ExtraBuiltinFunctionCall `{other}`"),
    }
}

fn eval_info(ctx: &mut EvalContext, e: &Expression) -> LayoutInfo {
    eval_expression(ctx, e).try_into().unwrap_or_default()
}

/// One flexbox cell as seen by the measure callback, after expanding
/// repeaters (a repeater contributes one entry per instance).
struct FlatCell<'a> {
    kind: FlatCellKind<'a>,
    w4h_only: bool,
}

enum FlatCellKind<'a> {
    Static {
        h_info: &'a Expression,
        v_info: &'a Expression,
    },
    Repeated(vtable::VRc<i_slint_core::item_tree::ItemTreeVTable, crate::instance::Instance>),
    /// No constrained layout info: the pre-resolved sizes are already correct.
    Fixed,
}

/// Flatten `measure_cells` into one entry per taffy cell. Static cells carry
/// their `(h_info, v_info)` expressions; a repeater expands to one instance
/// per row (re-measured through its own item tree at the assigned cross size).
fn flatten_measure_cells<'a>(
    ctx: &mut EvalContext,
    measure_cells: &'a [FlexboxMeasureCell],
) -> Vec<FlatCell<'a>> {
    let mut flat: Vec<FlatCell> = Vec::with_capacity(measure_cells.len());
    for item in measure_cells {
        match &item.kind {
            FlexboxMeasureCellKind::Static { h_info, v_info } => flat.push(FlatCell {
                kind: FlatCellKind::Static { h_info, v_info },
                w4h_only: item.w4h_only,
            }),
            FlexboxMeasureCellKind::Repeated(repeater) => {
                if let Some(current) = ctx.current.as_ref() {
                    let rep = &current.repeaters[repeater.repeater_index];
                    rep.track_instance_changes();
                    flat.extend(rep.instances_vec().into_iter().map(|instance| FlatCell {
                        kind: FlatCellKind::Repeated(instance),
                        w4h_only: item.w4h_only,
                    }));
                }
            }
            FlexboxMeasureCellKind::Fixed => {
                flat.push(FlatCell { kind: FlatCellKind::Fixed, w4h_only: item.w4h_only })
            }
        }
    }
    flat
}

/// Measure callback body shared by the solve and cross-axis-info paths:
/// re-evaluate the cell's perpendicular layout info with the
/// `measure_known_w` / `measure_known_h` local set to the dimension taffy
/// assigned (a dimension it did not assign, `known_* == false`, arrives
/// pre-resolved to the cell's preferred size). A probe with neither dimension
/// known measures the cell's free axis at the default size (see
/// `FlexboxMeasureFn` in i-slint-core).
fn measure_flexbox_cell(
    ctx: &mut EvalContext,
    flat: &[FlatCell],
    index: usize,
    w: f32,
    h: f32,
    known_w: bool,
    known_h: bool,
) -> (f32, f32) {
    let Some(cell) = flat.get(index) else { return (w, h) };
    // measure the height at the width `w`
    let measure_height = |ctx: &mut EvalContext| match &cell.kind {
        FlatCellKind::Static { v_info, .. } => {
            let prev = ctx.locals.insert("measure_known_w".into(), Value::Number(w as f64));
            let info = eval_info(ctx, v_info);
            crate::eval::restore_local(ctx, "measure_known_w", prev);
            (w, info.preferred_bounded())
        }
        FlatCellKind::Repeated(instance) => (
            w,
            instance
                .as_pin_ref()
                .flexbox_layout_item_info_at_cross_width(w)
                .constraint
                .preferred_bounded(),
        ),
        FlatCellKind::Fixed => (w, h),
    };
    // measure the width at the height `h`
    let measure_width = |ctx: &mut EvalContext| match &cell.kind {
        FlatCellKind::Static { h_info, .. } => {
            let prev = ctx.locals.insert("measure_known_h".into(), Value::Number(h as f64));
            let info = eval_info(ctx, h_info);
            crate::eval::restore_local(ctx, "measure_known_h", prev);
            (info.preferred_bounded(), h)
        }
        FlatCellKind::Repeated(instance) => (
            instance
                .as_pin_ref()
                .flexbox_layout_item_info_at_cross_height(h)
                .constraint
                .preferred_bounded(),
            h,
        ),
        FlatCellKind::Fixed => (w, h),
    };
    match (known_w, known_h) {
        (true, true) => (w, h),
        (true, false) => measure_height(ctx),
        (false, true) => measure_width(ctx),
        (false, false) => {
            if cell.w4h_only {
                measure_width(ctx)
            } else {
                measure_height(ctx)
            }
        }
    }
}

/// Interpret [`Expression::SolveFlexboxLayoutWithMeasure`].
pub(crate) fn solve_flexbox_layout_with_measure(ctx: &mut EvalContext, expr: &Expression) -> Value {
    let Expression::SolveFlexboxLayoutWithMeasure { data, repeater_indices, measure_cells } = expr
    else {
        return Value::Void;
    };
    let ri = to_u32_vec(&eval_expression(ctx, repeater_indices));
    let data = eval_expression(ctx, data);
    let Value::Struct(s) = &data else { return Value::LayoutCache(Default::default()) };
    let (ch, cv) = (
        s.get_field("cells_h").map(to_cells).unwrap_or_default(),
        s.get_field("cells_v").map(to_cells).unwrap_or_default(),
    );
    let fp = s.get_field("flex_props").map(to_flex_props).unwrap_or_default();

    let flat = flatten_measure_cells(ctx, measure_cells);
    let mut measure = |index: usize, w: f32, h: f32, known_w: bool, known_h: bool| {
        measure_flexbox_cell(ctx, &flat, index, w, h, known_w, known_h)
    };

    Value::LayoutCache(i_slint_core::layout::solve_flexbox_layout_with_measure(
        &FlexboxLayoutData {
            width: sf32(s, "width"),
            height: sf32(s, "height"),
            spacing_h: sf32(s, "spacing_h"),
            spacing_v: sf32(s, "spacing_v"),
            padding_h: s.get_field("padding_h").map(to_padding).unwrap_or_default(),
            padding_v: s.get_field("padding_v").map(to_padding).unwrap_or_default(),
            alignment: s.get_field("alignment").map(to_enum).unwrap_or_default(),
            direction: s.get_field("direction").map(to_enum).unwrap_or_default(),
            cross_axis_line_alignment: s
                .get_field("cross_axis_line_alignment")
                .map(to_enum)
                .unwrap_or_default(),
            cross_axis_alignment: s
                .get_field("cross_axis_alignment")
                .map(to_enum)
                .unwrap_or_default(),
            flex_wrap: s.get_field("flex_wrap").map(to_enum).unwrap_or_default(),
            cells_h: Slice::from_slice(&ch),
            cells_v: Slice::from_slice(&cv),
            flex_props: Slice::from_slice(&fp),
        },
        Slice::from_slice(&ri),
        Some(&mut measure),
    ))
}

/// Interpret [`Expression::FlexboxLayoutInfoCrossAxisWithMeasure`]: the
/// `flexbox_layout_info_cross_axis` builtin plus the measure callback, so
/// height-for-width cells are measured at the main-axis size taffy assigns
/// them rather than at the container size the cells were pre-measured at.
pub(crate) fn flexbox_layout_info_cross_axis_with_measure(
    ctx: &mut EvalContext,
    expr: &Expression,
) -> Value {
    let Expression::FlexboxLayoutInfoCrossAxisWithMeasure { arguments, measure_cells } = expr
    else {
        return Value::Void;
    };
    let a: Vec<Value> = arguments.iter().map(|e| eval_expression(ctx, e)).collect();
    let (ch, cv) = (to_cells(&a[0]), to_cells(&a[1]));
    let fp = to_flex_props(&a[2]);
    let flat = flatten_measure_cells(ctx, measure_cells);
    let mut measure = |index: usize, w: f32, h: f32, known_w: bool, known_h: bool| {
        measure_flexbox_cell(ctx, &flat, index, w, h, known_w, known_h)
    };
    i_slint_core::layout::flexbox_layout_info_cross_axis_with_measure(
        Slice::from_slice(&ch),
        Slice::from_slice(&cv),
        Slice::from_slice(&fp),
        to_f32(&a[3]),
        to_f32(&a[4]),
        &to_padding(&a[5]),
        &to_padding(&a[6]),
        to_enum(&a[7]),
        to_enum(&a[8]),
        to_enum(&a[9]),
        to_f32(&a[10]),
        Some(&mut measure),
    )
    .into()
}
